const fetchImage = async () => {
    const imageUrl = 'http://host.docker.internal:3000/vercel.svg';
    const response = await fetch(imageUrl);
    if (!response.ok) {
        throw new Error(`Failed to fetch image: ${response.statusText}`);
    }
    const blob = await response.blob();
    const image = new Image();
    image.src = URL.createObjectURL(blob);

    // Extract metadata from the image
    const metadata = {
        type: 'SVG',
        width: image.naturalWidth || 'Unknown',
        height: image.naturalHeight || 'Unknown',
        mimeType: response.headers.get('content-type') || 'image/svg+xml',
        description: 'Vercel logo SVG',
        dimensions: {
            width: image.naturalWidth,
            height: image.naturalHeight
        },
        // Additional metadata extraction for SVG
        ...(await extractSVGMetadata(blob)),
    };

    return metadata;
};

// Helper function to extract SVG metadata (simplified)
const extractSVGMetadata = async (blob) => {
    const arrayBuffer = await blob.arrayBuffer();
    const svgText = new TextDecoder('utf-8').decode(arrayBuffer);

    // Extract common metadata attributes from SVG
    const metadata = {}
    const attributes = svgText.match(/<svg[^>]*([^>]*)>/i) || [];

    if (attributes[1]) {
        const attributesObj = new DOMParser().parseFromString(attributes[1], 'text/xml').documentElement.attributes;
        for (const attr of attributesObj) {
            if (attr.name !== 'xmlns' && attr.name !== 'xmlns:xlink') { // Ignore common namespaces
                metadata[attr.name] = attr.value;
            }
        }
    }

    return metadata;
};

// Execute the function to fetch and inspect the image
fetchImage().then(metadata => {
    console.log(metadata);
    return metadata;
});

